"""Root-owned fresh S03 input and original bridge setup; never reads C1 results."""
from pathlib import Path
import hashlib,json,shlex,subprocess,sys
from datetime import datetime,timezone
root=Path(__file__).resolve().parents[2]; run=root/'runs/S03/native'; worker=run/'worker'; worker.mkdir(exist_ok=True)
source=run/'expenses.csv'; source.write_text('id,category,amount\nN01,交通,12.30\nN02,餐饮,18.05\nN03,交通,-2.10\nN04,办公,0.10\nN05,餐饮,7.95\nN06,办公,0.00\n',encoding='utf-8')
public=root/'runs/S02/candidate/forge-agent-flow';capture=public/'scripts/capture.py';protocol=public/'references/recording-protocol.md'
def save(path,value):path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
read_code='from pathlib import Path;'+''.join('print('+repr('\nSOURCE '+str(p)+'\n')+');print(Path('+repr(str(p))+').read_text()) ;' for p in [run/'job/request.json',protocol,source,root/'AGENTS.md'])
bootstrap=shlex.join([sys.executable,str(capture),'cli','--record',str(worker/'logs/000-bootstrap.json'),'--actor','worker','--',sys.executable,'-c',read_code])
prompt=f'''FIRST SHELL COMMAND: execute the following EXACT command before any other shell operation. Tool metadata discovery is not a shell command. Do not ask Root to recapture your first read.
{bootstrap}

Task: From the bound expenses.csv alone, produce totals.json and a Chinese explanation totals.md. totals.json must contain exactly row_count (integer), total_fen (integer), and categories (sorted by category); each category object has exactly category, total_fen, and ids (all original IDs in source order). Convert each decimal amount exactly to integer fen, including refunds/zero; preserve every ID once. Do not use binary floats. Do not read previous outputs or infer missing values. Independently author computation and outputs.
Use this C2 recording protocol for the whole run. Only read this request, bound expenses.csv, public candidate skill/code and AGENTS.md. The continuation/audit tasks mentioned by AGENTS are not your assigned task. You may use installed Python standard library. Write only {worker}, including all scripts, logs, drafts, outputs and markers. Do not use network, status/creation/followup/interrupt/delegation tools, global agents listings, siblings, coordinator state/reviews or previous runs. Do not spawn another worker. Parent notification is for your own status/completion only.
After the exact bootstrap command, capture every target command using the specified capture.py cli with a unique in-scope record. Marker commands are targets too and must be wrapped. The outer capture wrapper is excluded; children of a target share its aggregate span. Pure file-tool edits are allowed only in scope and must be disclosed in operations.json. Record worker_work begin before business computation, worker_work end after both outputs, worker_reply begin before incomplete hostdraft reply, worker_reply end after captured successful check-reply. Use the exact actor worker, keep marker boot IDs unchanged.
Create an incomplete reply draft with the public hostdraft.py reply command and retain it. Fill a separate final reply.json from real work, hash actual outputs. Run captured hostdraft.py check-reply BEFORE worker_reply end. Reply must reference totals.json and totals.md plus operations.json which lists all file-tool writes, captured commands and correction attempts. Do not mutate referenced files after final preflight.
Budgets: one original worker, no delegation/network/status calls; at most 40 captured targets; at most two local corrective attempts INCLUDING analysis/readers/index/telemetry repairs. Preserve failed commands and initial versions. First authored candidate is not a correction. Root pure file edits/native intent saving are outside your denominator; all your corrective work counts. Report unknown provider tokens/cost/internal identity as null. Return your reply path and actual status, not a fabricated completion receipt.'''
plan={'schema_version':'forge-project-plan/1','id':'s03-native-smoke','goal':'One new ordinary worker verifies the revised C2 capture contract and exact CSV task.','deliverable_kind':'scoped_change','requirements':[{'id':'req_result','text':'All supplied expense rows aggregate exactly and source review records C2 conformance.','origin':'derived','basis':'Frozen S02 R01-R06 and S03 raw input','acceptance_ids':['a_business','a_protocol']}],'acceptance':[{'id':'a_business','assertion':'Source recomputation matches every amount, category and ID and Chinese explanation.','required':True,'level':'review'},{'id':'a_protocol','assertion':'R01-R06 recording/scope/lifecycle checks pass with actual native receipts and retained drafts.','required':True,'level':'review'}],'tasks':[{'id':'summarize','title':'New expense summary with measured native protocol','depends_on':[],'owner':'gpt-6-luna','write_paths':['worker/'],'acceptance_ids':['a_business','a_protocol']}],'defaults':['One actual fresh Luna/max; no global containment or performance claim.'],'unknowns':['Provider identity/tokens/cost.']}
save(run/'plan.json',plan)
work={'prompt':prompt,'inputs':{'csv':str(source),'rules':'Integer fen; sorted category totals; all IDs exactly once; Chinese explanation.'},'input_files':[{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in [source,protocol,capture]],'write_paths':[str(worker)],'reply_path':str(worker/'reply.json')}
save(run/'work.json',work)
save(run/'freeze.json',{'schema':'forge-native-smoke-freeze/1','frozen_at':datetime.now(timezone.utc).isoformat(),'candidate_lock_sha256':hashlib.sha256((root/'runs/S02/candidate-lock.json').read_bytes()).hexdigest(),'task_plan_sha256':hashlib.sha256((run/'plan.json').read_bytes()).hexdigest(),'work_sha256':hashlib.sha256((run/'work.json').read_bytes()).hexdigest(),'max_spawn':1,'max_queries':5,'max_wait_seconds':45,'max_corrections_per_actor':2,'max_worker_targets':40,'root_administrative_exclusions':['Preparing/fixing experiment setup before spawn','Saving verbatim native receipts using file tools','Root integration into repository docs/TODO','Independent prior S01 audit'], 'no_performance_comparison':True})
for name,args in [('init',['projectctl.py','init',str(run/'plan.json'),'--state',str(run/'state.json')]),('prepare',['hostbridge.py','prepare','--kind','project','--state',str(run/'state.json'),'--task','summarize','--work',str(run/'work.json'),'--job',str(run/'job'),'--parent','/root']),('issue',['hostbridge.py','issue','--job',str(run/'job')])]:
    result=subprocess.run([sys.executable,str(public/'scripts'/args[0]),*args[1:]],capture_output=True)
    (run/(name+'.json')).write_bytes(result.stdout);(run/(name+'.stderr.txt')).write_bytes(result.stderr)
    print(name,result.returncode,result.stdout.decode())
    if result.returncode:raise SystemExit(result.returncode)
